import type { GetDocuments, GetDocument } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const getDocuments: GetDocuments<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  return context.entities.Document.findMany({
    where: {
      OR: [
        { ownerId: userId },
        {
          permissions: {
            some: {
              userId: userId,
            },
          },
        },
      ],
    },
    include: {
      owner: {
        select: {
          id: true,
          username: true,
        },
      },
      permissions: {
        where: {
          userId: userId,
        },
      },
    },
    orderBy: {
      updatedAt: "desc",
    },
  });
};

export const getDocument: GetDocument<{ id: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: {
      owner: {
        select: {
          id: true,
          username: true,
        },
      },
      versions: {
        include: {
          author: {
            select: {
              username: true,
            },
          },
        },
        orderBy: {
          createdAt: "desc",
        },
      },
      permissions: {
        include: {
          user: {
            select: {
              username: true,
            },
          },
        },
      },
    },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === userId;
  const userPermission = doc.permissions.find((p) => p.userId === userId);

  if (!isOwner && !userPermission) {
    throw new HttpError(403, "Access Denied");
  }

  const role = isOwner ? "OWNER" : userPermission.role;

  return {
    ...doc,
    role,
  };
};

import type {
  CreateDocument,
  SaveVersion,
  RestoreVersion,
  ShareDocument,
  RevokePermission,
} from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const createDocument: CreateDocument<{ title: string }, any> = async (
  args,
  context
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  if (!args.title || args.title.trim() === "") {
    throw new HttpError(400, "Title is required");
  }

  return context.entities.Document.create({
    data: {
      title: args.title,
      content: "",
      ownerId: context.user.id,
    },
  });
};

export const saveVersion: SaveVersion<
  { documentId: number; content: string },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  const doc = await context.entities.Document.findUnique({
    where: { id: args.documentId },
    include: {
      permissions: {
        where: { userId },
      },
    },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === userId;
  const hasEditPermission = doc.permissions.some((p) => p.role === "EDIT");

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(
      403,
      "Access Denied: You do not have permission to edit this document"
    );
  }

  // Update document content
  await context.entities.Document.update({
    where: { id: args.documentId },
    data: { content: args.content },
  });

  // Create a new version
  return context.entities.Version.create({
    data: {
      documentId: args.documentId,
      content: args.content,
      authorId: userId,
    },
  });
};

export const restoreVersion: RestoreVersion<{ versionId: number }, any> = async (
  args,
  context
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  const version = await context.entities.Version.findUnique({
    where: { id: args.versionId },
    include: {
      document: {
        include: {
          permissions: {
            where: { userId },
          },
        },
      },
    },
  });

  if (!version) {
    throw new HttpError(404, "Version not found");
  }

  const doc = version.document;
  const isOwner = doc.ownerId === userId;
  const hasEditPermission = doc.permissions.some((p) => p.role === "EDIT");

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(
      403,
      "Access Denied: You do not have permission to edit this document"
    );
  }

  // Update document active content
  await context.entities.Document.update({
    where: { id: doc.id },
    data: { content: version.content },
  });

  return {
    documentId: doc.id,
    content: version.content,
  };
};

export const shareDocument: ShareDocument<
  { documentId: number; username: string; role: string },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  const doc = await context.entities.Document.findUnique({
    where: { id: args.documentId },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  if (doc.ownerId !== userId) {
    throw new HttpError(403, "Only the owner can share this document");
  }

  const targetUser = await context.entities.User.findUnique({
    where: { username: args.username },
  });

  if (!targetUser) {
    throw new HttpError(404, `User "${args.username}" not found`);
  }

  if (targetUser.id === userId) {
    throw new HttpError(400, "You cannot share the document with yourself");
  }

  return context.entities.Permission.upsert({
    where: {
      documentId_userId: {
        documentId: args.documentId,
        userId: targetUser.id,
      },
    },
    update: {
      role: args.role,
    },
    create: {
      documentId: args.documentId,
      userId: targetUser.id,
      role: args.role,
    },
  });
};

export const revokePermission: RevokePermission<
  { permissionId: number },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  const permission = await context.entities.Permission.findUnique({
    where: { id: args.permissionId },
    include: {
      document: true,
    },
  });

  if (!permission) {
    throw new HttpError(404, "Permission not found");
  }

  if (permission.document.ownerId !== userId) {
    throw new HttpError(403, "Only the owner can revoke permissions");
  }

  return context.entities.Permission.delete({
    where: { id: args.permissionId },
  });
};

import { type WebSocketDefinition, type WaspSocketData } from "wasp/server/webSocket";

export const webSocketFn: WebSocketFn = (io, context) => {
  io.on("connection", (socket) => {
    const userId = socket.data.user?.id;
    const username = socket.data.user?.username ?? "Unknown";
    console.log(`User connected: ${username} (ID: ${userId})`);

    socket.on("joinDocument", async ({ documentId }) => {
      // Join the room for this document
      const roomName = `document-${documentId}`;
      socket.join(roomName);
      console.log(`User ${username} joined room ${roomName}`);
    });

    socket.on("editDocument", async ({ documentId, content }) => {
      if (!userId) return;

      try {
        // Permission check
        const doc = await context.entities.Document.findUnique({
          where: { id: documentId },
          include: {
            permissions: {
              where: { userId },
            },
          },
        });

        if (!doc) return;

        const isOwner = doc.ownerId === userId;
        const hasEditPermission = doc.permissions.some((p) => p.role === "EDIT");

        if (!isOwner && !hasEditPermission) {
          console.log(`Edit denied for user ${username} on document ${documentId}`);
          return;
        }

        // Update database
        await context.entities.Document.update({
          where: { id: documentId },
          data: { content },
        });

        // Broadcast to all other users in the room
        socket.to(`document-${documentId}`).emit("documentUpdated", {
          documentId,
          content,
        });
      } catch (err) {
        console.error("Error handling editDocument:", err);
      }
    });

    socket.on("broadcastRestore", async ({ documentId, content }) => {
      if (!userId) return;

      try {
        // Permission check
        const doc = await context.entities.Document.findUnique({
          where: { id: documentId },
          include: {
            permissions: {
              where: { userId },
            },
          },
        });

        if (!doc) return;

        const isOwner = doc.ownerId === userId;
        const hasEditPermission = doc.permissions.some((p) => p.role === "EDIT");

        if (!isOwner && !hasEditPermission) {
          return;
        }

        // Broadcast to all other users in the room
        socket.to(`document-${documentId}`).emit("documentUpdated", {
          documentId,
          content,
        });
      } catch (err) {
        console.error("Error handling broadcastRestore:", err);
      }
    });
  });
};

type WebSocketFn = WebSocketDefinition<
  ClientToServerEvents,
  ServerToClientEvents,
  InterServerEvents,
  SocketData
>;

interface ServerToClientEvents {
  documentUpdated: (data: { documentId: number; content: string }) => void;
}

interface ClientToServerEvents {
  joinDocument: (data: { documentId: number }) => void;
  editDocument: (data: { documentId: number; content: string }) => void;
  broadcastRestore: (data: { documentId: number; content: string }) => void;
}

interface InterServerEvents {}

interface SocketData extends WaspSocketData {}

import { useState } from "react";
import { Link } from "react-router";
import { logout } from "wasp/client/auth";
import { useQuery, getDocuments, createDocument } from "wasp/client/operations";
import type { AuthUser } from "wasp/auth";

export function MainPage({ user }: { user: AuthUser }) {
  const { data: documents, error, isLoading } = useQuery(getDocuments);
  const [newTitle, setNewTitle] = useState("");
  const [createError, setCreateError] = useState("");

  const handleCreateDocument = async (e: React.FormEvent) => {
    e.preventDefault();
    setCreateError("");
    if (!newTitle.trim()) {
      setCreateError("Title is required");
      return;
    }

    try {
      await createDocument({ title: newTitle });
      setNewTitle("");
    } catch (err: any) {
      setCreateError(err.message || "Failed to create document");
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <nav className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center">
              <span className="text-xl font-bold text-blue-600">CollabEdit</span>
            </div>
            <div className="flex items-center space-x-4">
              <span className="text-sm text-gray-700">
                Logged in as <strong className="font-semibold">{user.username}</strong>
              </span>
              <button
                onClick={logout}
                className="px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto py-10 px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 gap-8 md:grid-cols-3">
          {/* Create Document Form */}
          <div className="bg-white p-6 rounded-lg shadow-md border border-gray-200 h-fit">
            <h3 className="text-lg font-bold text-gray-900 mb-4">Create New Document</h3>
            <form onSubmit={handleCreateDocument} className="space-y-4">
              <div>
                <label htmlFor="document-title-input" className="block text-sm font-medium text-gray-700 mb-1">
                  Document Title
                </label>
                <input
                  type="text"
                  id="document-title-input"
                  value={newTitle}
                  onChange={(e) => setNewTitle(e.target.value)}
                  placeholder="e.g. Project Proposal"
                  className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                />
              </div>
              {createError && <p className="text-sm text-red-600">{createError}</p>}
              <button
                type="submit"
                id="create-document-btn"
                className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
              >
                Create Document
              </button>
            </form>
          </div>

          {/* Document List */}
          <div className="md:col-span-2 bg-white p-6 rounded-lg shadow-md border border-gray-200">
            <h3 className="text-lg font-bold text-gray-900 mb-6">Your Documents</h3>

            {isLoading && <p className="text-gray-600">Loading documents...</p>}
            {error && <p className="text-red-600">Error loading documents: {error.message}</p>}

            {!isLoading && !error && (!documents || documents.length === 0) && (
              <div className="text-center py-12 border-2 border-dashed border-gray-300 rounded-lg">
                <p className="text-gray-500">No documents found. Create one to get started!</p>
              </div>
            )}

            {!isLoading && !error && documents && documents.length > 0 && (
              <div className="overflow-hidden shadow ring-1 ring-black ring-opacity-5 md:rounded-lg">
                <table className="min-w-full divide-y divide-gray-300">
                  <thead className="bg-gray-50">
                    <tr>
                      <th scope="col" className="py-3.5 pl-4 pr-3 text-left text-sm font-semibold text-gray-900 sm:pl-6">
                        Title
                      </th>
                      <th scope="col" className="px-3 py-3.5 text-left text-sm font-semibold text-gray-900">
                        Owner
                      </th>
                      <th scope="col" className="px-3 py-3.5 text-left text-sm font-semibold text-gray-900">
                        Access
                      </th>
                      <th scope="col" className="relative py-3.5 pl-3 pr-4 sm:pr-6">
                        <span className="sr-only">Open</span>
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 bg-white">
                    {documents.map((doc: any) => {
                      const isOwner = doc.ownerId === user.id;
                      const accessRole = isOwner ? "Owner" : doc.permissions[0]?.role || "VIEW";
                      return (
                        <tr key={doc.id}>
                          <td className="whitespace-nowrap py-4 pl-4 pr-3 text-sm font-medium text-gray-900 sm:pl-6">
                            <Link to={`/document/${doc.id}`} className="text-blue-600 hover:text-blue-900 hover:underline">
                              {doc.title}
                            </Link>
                          </td>
                          <td className="whitespace-nowrap px-3 py-4 text-sm text-gray-500">
                            {isOwner ? "me" : doc.owner.username}
                          </td>
                          <td className="whitespace-nowrap px-3 py-4 text-sm text-gray-500">
                            <span
                              className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                                accessRole === "Owner"
                                  ? "bg-green-100 text-green-800"
                                  : accessRole === "EDIT"
                                  ? "bg-blue-100 text-blue-800"
                                  : "bg-gray-100 text-gray-800"
                              }`}
                            >
                              {accessRole}
                            </span>
                          </td>
                          <td className="whitespace-nowrap py-4 pl-3 pr-4 text-right text-sm font-medium sm:pr-6">
                            <Link to={`/document/${doc.id}`} className="text-blue-600 hover:text-blue-900">
                              Open
                            </Link>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}
export default MainPage;

import { useState, useEffect } from "react";
import { useParams, Link } from "react-router";
import { useQuery, getDocument, saveVersion, restoreVersion, shareDocument, revokePermission } from "wasp/client/operations";
import { useSocket, useSocketListener } from "wasp/client/webSocket";
import type { AuthUser } from "wasp/auth";

export function DocumentPage({ user }: { user: AuthUser }) {
  const { id } = useParams();
  const documentId = parseInt(id || "");

  const { data: document, error, isLoading } = useQuery(getDocument, { id: documentId });

  const [content, setContent] = useState("");
  const [hasInitializedContent, setHasInitializedContent] = useState(false);

  // Sharing form state
  const [shareUsername, setShareUsername] = useState("");
  const [shareRole, setShareRole] = useState("VIEW");
  const [shareError, setShareError] = useState("");
  const [shareSuccess, setShareRoleSuccess] = useState("");

  // Version saving state
  const [saveStatus, setSaveStatus] = useState("");

  const { socket, isConnected } = useSocket();

  // Initialize content once the document query completes
  useEffect(() => {
    if (document) {
      if (!hasInitializedContent) {
        setContent(document.content);
        setHasInitializedContent(true);
      }
    }
  }, [document, hasInitializedContent]);

  // Join document room on mount/connect
  useEffect(() => {
    if (documentId && isConnected) {
      socket.emit("joinDocument", { documentId });
    }
  }, [documentId, isConnected, socket]);

  // Listen for real-time document updates
  useSocketListener("documentUpdated", ({ documentId: updatedDocId, content: updatedContent }) => {
    if (updatedDocId === documentId) {
      setContent(updatedContent);
    }
  });

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <p className="text-gray-600 text-lg">Loading document...</p>
      </div>
    );
  }

  if (error) {
    const isAccessDenied = error.status === 403 || error.message?.includes("Access Denied");
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 px-4">
        <div className="max-w-md w-full text-center bg-white p-8 rounded-lg shadow-md border border-gray-200">
          <h2 className="text-3xl font-bold text-red-600 mb-2">
            {isAccessDenied ? "Access Denied" : "Error"}
          </h2>
          <p className="text-gray-600 mb-6">
            {isAccessDenied
              ? "You do not have permission to view or edit this document."
              : error.message || "An error occurred while loading the document."}
          </p>
          <Link
            to="/"
            className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700"
          >
            Back to Dashboard
          </Link>
        </div>
      </div>
    );
  }

  if (!document) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
        <p className="text-gray-600 text-lg mb-4">Document not found.</p>
        <Link to="/" className="text-blue-600 hover:underline">
          Back to Dashboard
        </Link>
      </div>
    );
  }

  const isOwner = document.role === "OWNER";
  const canEdit = isOwner || document.role === "EDIT";

  const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newContent = e.target.value;
    setContent(newContent);
    socket.emit("editDocument", { documentId, content: newContent });
  };

  const handleSaveVersion = async () => {
    setSaveStatus("Saving...");
    try {
      await saveVersion({ documentId, content });
      setSaveStatus("Version saved successfully!");
      setTimeout(() => setSaveStatus(""), 3000);
    } catch (err: any) {
      setSaveStatus(`Failed to save: ${err.message}`);
    }
  };

  const handleRestoreVersion = async (versionId: number, versionContent: string) => {
    if (!confirm("Are you sure you want to restore this version? Any unsaved edits will be overwritten.")) {
      return;
    }
    try {
      await restoreVersion({ versionId });
      setContent(versionContent);
      socket.emit("broadcastRestore", { documentId, content: versionContent });
    } catch (err: any) {
      alert(`Failed to restore: ${err.message}`);
    }
  };

  const handleShare = async (e: React.FormEvent) => {
    e.preventDefault();
    setShareError("");
    setShareRoleSuccess("");

    if (!shareUsername.trim()) {
      setShareError("Username is required");
      return;
    }

    try {
      await shareDocument({ documentId, username: shareUsername, role: shareRole });
      setShareRoleSuccess(`Successfully shared with ${shareUsername}`);
      setShareUsername("");
    } catch (err: any) {
      setShareError(err.message || "Failed to share document");
    }
  };

  const handleRevoke = async (permissionId: number) => {
    if (!confirm("Are you sure you want to revoke this user's access?")) {
      return;
    }
    try {
      await revokePermission({ permissionId });
    } catch (err: any) {
      alert(`Failed to revoke access: ${err.message}`);
    }
  };

  // Chronological order: oldest first
  const chronologicalVersions = [...document.versions].sort(
    (a: any, b: any) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
  );

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Top Navbar */}
      <nav className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center space-x-4">
              <Link to="/" className="text-blue-600 hover:text-blue-900 font-medium text-sm">
                &larr; Dashboard
              </Link>
              <span className="text-gray-300">|</span>
              <h1 className="text-xl font-bold text-gray-900">{document.title}</h1>
            </div>
            <div className="flex items-center space-x-4">
              <span
                className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                  isConnected ? "bg-green-100 text-green-800" : "bg-red-100 text-red-800"
                }`}
              >
                {isConnected ? "🟢 Connected" : "🔴 Disconnected"}
              </span>
              <span className="text-sm text-gray-500">
                Your Access: <strong className="text-gray-800">{document.role}</strong>
              </span>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Workspace Area */}
      <div className="max-w-7xl mx-auto w-full py-6 px-4 sm:px-6 lg:px-8 flex-1 grid grid-cols-1 gap-8 lg:grid-cols-3">
        {/* Editor Area */}
        <div className="lg:col-span-2 flex flex-col space-y-4">
          <div className="flex-1 bg-white p-6 rounded-lg shadow-md border border-gray-200 flex flex-col min-h-[500px]">
            <label htmlFor="document-content-textarea" className="sr-only">
              Document Content
            </label>
            <textarea
              id="document-content-textarea"
              value={content}
              onChange={handleContentChange}
              disabled={!canEdit}
              placeholder={canEdit ? "Start typing here..." : "You have view-only access to this document."}
              className="w-full flex-1 p-4 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none font-mono text-sm leading-relaxed"
            />
          </div>

          {canEdit && (
            <div className="flex items-center justify-between">
              <button
                id="save-version-btn"
                onClick={handleSaveVersion}
                className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
              >
                Save Version
              </button>
              {saveStatus && <span className="text-sm text-gray-600 font-medium">{saveStatus}</span>}
            </div>
          )}
        </div>

        {/* Sidebar (Sharing & Version History) */}
        <div className="space-y-8">
          {/* Document Sharing (Only for Owner) */}
          {isOwner && (
            <div className="bg-white p-6 rounded-lg shadow-md border border-gray-200">
              <h3 className="text-lg font-bold text-gray-900 mb-4">Share Document</h3>
              <form onSubmit={handleShare} className="space-y-4 mb-6">
                <div>
                  <label htmlFor="share-username-input" className="block text-sm font-medium text-gray-700 mb-1">
                    Username
                  </label>
                  <input
                    type="text"
                    id="share-username-input"
                    value={shareUsername}
                    onChange={(e) => setShareUsername(e.target.value)}
                    placeholder="Enter username"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                  />
                </div>
                <div>
                  <label htmlFor="share-role-select" className="block text-sm font-medium text-gray-700 mb-1">
                    Role
                  </label>
                  <select
                    id="share-role-select"
                    value={shareRole}
                    onChange={(e) => setShareRole(e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                  >
                    <option value="VIEW">VIEW</option>
                    <option value="EDIT">EDIT</option>
                  </select>
                </div>
                {shareError && <p className="text-sm text-red-600">{shareError}</p>}
                {shareSuccess && <p className="text-sm text-green-600">{shareSuccess}</p>}
                <button
                  type="submit"
                  id="share-document-btn"
                  className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                >
                  Share
                </button>
              </form>

              {/* Permissions List */}
              <div>
                <h4 className="text-sm font-bold text-gray-700 mb-2 border-b pb-1">Current Permissions</h4>
                {document.permissions.length === 0 ? (
                  <p className="text-sm text-gray-500 italic">Not shared with anyone yet.</p>
                ) : (
                  <ul id="permissions-list" className="space-y-3">
                    {document.permissions.map((perm: any) => (
                      <li key={perm.id} className="flex justify-between items-center text-sm bg-gray-50 p-2 rounded border border-gray-150">
                        <div>
                          <span className="font-semibold text-gray-800">{perm.user.username}</span>
                          <span className="ml-2 text-xs font-medium text-gray-500 bg-gray-200 px-1.5 py-0.5 rounded">
                            {perm.role}
                          </span>
                        </div>
                        <button
                          onClick={() => handleRevoke(perm.id)}
                          className="text-xs text-red-600 hover:text-red-900 font-medium"
                        >
                          Revoke
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>
          )}

          {/* Version History */}
          <div className="bg-white p-6 rounded-lg shadow-md border border-gray-200">
            <h3 className="text-lg font-bold text-gray-900 mb-4">Version History</h3>
            {chronologicalVersions.length === 0 ? (
              <p className="text-sm text-gray-500 italic">No saved versions yet.</p>
            ) : (
              <ul id="version-history-list" className="space-y-4">
                {chronologicalVersions.map((v: any, index: number) => (
                  <li key={v.id} className="p-3 bg-gray-50 rounded border border-gray-200 flex flex-col space-y-2">
                    <div className="flex justify-between items-start">
                      <div>
                        <p className="text-sm font-bold text-gray-800">Version #{index + 1}</p>
                        <p className="text-xs text-gray-500">ID: {v.id}</p>
                        <p className="text-xs text-gray-500 mt-1">
                          Saved by <span className="font-semibold text-gray-700">{v.author.username}</span>
                        </p>
                        <p className="text-[10px] text-gray-400 mt-0.5">
                          {new Date(v.createdAt).toLocaleString()}
                        </p>
                      </div>
                      {canEdit && (
                        <button
                          onClick={() => handleRestoreVersion(v.id, v.content)}
                          className="restore-version-btn inline-flex items-center px-2 py-1 border border-blue-600 rounded text-xs font-semibold text-blue-600 bg-white hover:bg-blue-50"
                        >
                          Restore
                        </button>
                      )}
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
export default DocumentPage;

